mapper.update:
UPDATE sys_pms_recommendation
SET status = #{status}, approval_policy = #{approvalPolicy}, rejection_reason = #{rejectionReason},
    execution_result = #{executionResult}, measured_result = #{measuredResult}, updated_at = #{updatedAt}
WHERE erp_reference_id = #{erpReferenceId} AND tenant_id = #{tenantId}

